local UIFishPoolAutoSettlementDialog = Class("UIFishPoolAutoSettlementDialog")

function UIFishPoolAutoSettlementDialog:__init() 
    self._rewards = {}
end 

function UIFishPoolAutoSettlementDialog:__delete()
    self._rewards = {}
end

