end

function UIFishPoolAutoSettlementDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CS.UnityEngine.Time.timeScale = 1
        self:FillSelf()
    end))
    return coWait
