function UIFishPoolAutoSettlementDialog:InitData()
    local t = fishingComponent:GetAutoRewards()
    for i = 1, #t do
        for j = i + 1, #t do
            local b = t[i]
            local a = t[j]

            local isTrue = false
            local vo1 = GoodsConfMgr:GetInstance():GetGoodsVoById(a.goodsId)
            local vo2 = GoodsConfMgr:GetInstance():GetGoodsVoById(b.goodsId)
            
            if checkNumber(vo1.quality) == checkNumber(vo2.quality) then
                isTrue = checkNumber(a.goodsId) < checkNumber(b.goodsId)
            else
                isTrue = checkNumber(vo2.quality) < checkNumber(vo1.quality)
            end

            if isTrue then
                local data = a
                t[j] = b
                t[i] = data
            end
        end
    end

    local ind = 0
    for i = 1, #t do
        local a = t[i]
        if checkNumber(a.goodsId) == Constants.Currency.GoldId then
            ind = i
            break
        end
    end
    if ind > 0 then
        local data = t[ind]
        table.remove(t, ind)
        table.insert(t, 1, data)
    end
    self._rewards = t
end

function UIFishPoolAutoSettlementDialog:FillSelf()
    local isHaveRewards = table.count(self._rewards) > 0
    CfUtils.SetActive(self.DescInformationNode, true)
    CfUtils.SetActive(self.RewardListNode, isHaveRewards)

    self:FillTitle()
    if isHaveRewards then
        self:FillRewards()
    end
end

function UIFishPoolAutoSettlementDialog:FillTitle()
    local isAllFinish = (FishingUtils.GetRemainAutoNum() <= 0)
    CfUtils.SetUISwitchImage(self.DescInformationNode.transform:Find("SymbolNode/ImgSymbol"), isAllFinish and 2 or 1)

    local isHaveRewards = table.count(self._rewards) > 0
    local num = fishingComponent:GetAutoFinishNum()
    CfUtils.SetActive(self.TextFrequency, ((num > 0) and not isHaveRewards))
    CfUtils.FillText(self.TextFrequency, localize("(当前已垂钓_num_次)", {_num_ = num}))
    CfUtils.SetActive(self.TextTitle, ((num > 0) and isHaveRewards))
    CfUtils.FillText(self.TextTitle, localize("當前已垂釣_num_次，獲得以下獎勵：", {_num_ = num}))
    local remainNum = FishingUtils.GetRemainAutoNum()
    if self._isNotEnough then
        CfUtils.FillText(self.DescInformationNode.transform:Find("DescNode/TextDesc"), localize("哎呀……新海币不够了\n等有了更多的新海币再来吧~"))
    elseif self._isFail then --  remainNum <= 0 or self._isHandExit then
        CfUtils.FillText(self.DescInformationNode.transform:Find("DescNode/TextDesc"), localize("哎呀……鱼儿跑掉了\n请调查官<size=44><color=#ef28a4>更换渔具</color></size>再试一次"))
    else
        CfUtils.FillText(self.DescInformationNode.transform:Find("DescNode/TextDesc"), localize("自律完成！"))
    end
end

function UIFishPoolAutoSettlementDialog:FillRewards()
    local isAllFinish = (FishingUtils.GetRemainAutoNum() <= 0)
    local num = fishingComponent:GetAutoFinishNum()
    CfUtils.FillText(self.TextTitle, localize("当前已垂钓_num_次，获得以下奖励：", {_num_ = num}))

    self.ScrollView:InitGridView(table.count(self._rewards), Bind(self, self.OnRefreshPartsIndex))
end 

function UIFishPoolAutoSettlementDialog:OnRefreshPartsIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")

    local data = self._rewards[index + 1]
    local node = cell.gameObject.transform:Find("GoodNode")
    CfUtils.RefeshGoodGo2(node, data.goodsId, "x"..data.num, nil, nil, function()
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
        GameUtils.ShowCommonTipsBoard(node, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
    end)

    return cell
end

function UIFishPoolAutoSettlementDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        SetButtonAction(self.BtnClose, function()
            UIModule.BackDialog()
        end)
        SetButtonAction(self.ImgBlack, function()
            UIModule.BackDialog()
        end)
        local argument = self.controller.Argument.parameters
        if argument then
            self._isHandExit = (argument.isHandExit)
            self._isFail = (argument.isFail)
            self._isNotEnough = (argument.isNotEnough)
        end

        self:InitData()
    end))
    return coWait
end

